class Solution:
    def validSubstringCount(self, word1: str, word2: str) -> int:
        from collections import Counter
        need = Counter(word2)
        ans = 0
        for i in range(len(word1)):
            c = Counter()
            for j in range(i, len(word1)):
                c[word1[j]] += 1
                if all(c[x] >= need[x] for x in need):
                    ans += 1
        return ans

