class Solution {
public:
    long long validSubstringCount(string word1, string word2) {
        int need[26] = {0};
        for (char ch : word2) need[ch - 'a']++;
        long long ans = 0;
        int n = word1.size();
        for (int i = 0; i < n; i++) {
            int c[26] = {0};
            for (int j = i; j < n; j++) {
                c[word1[j]-'a']++;
                bool ok = true;
                for (int k = 0; k < 26 && ok; k++)
                    if (c[k] < need[k]) ok = false;
                if (ok) ans++;
            }
        }
        return ans;
    }
};

