class Solution:
    def validSubstringCount(self, word1: str, word2: str) -> int:
        from collections import Counter
        need = Counter(word2)
        cnt = Counter()
        miss = len(need)
        left = 0
        ans = 0
        for ch in word1:
            cnt[ch] += 1
            if ch in need and cnt[ch] == need[ch]:
                miss -= 1
            while miss == 0:
                lc = word1[left]
                if lc in need and cnt[lc] == need[lc]:
                    miss += 1
                cnt[lc] -= 1
                left += 1
            ans += left
        return ans

