class Solution {
public:
    long long validSubstringCount(string word1, string word2) {
        int need[26] = {0}, cnt[26] = {0};
        int miss = 0;
        for (char ch : word2) if (need[ch-'a']++ == 0) miss++;
        long long ans = 0;
        int left = 0;
        for (char ch : word1) {
            int x = ch - 'a';
            if (++cnt[x] == need[x] && need[x] > 0) miss--;
            while (miss == 0) {
                int y = word1[left++] - 'a';
                if (need[y] > 0 && cnt[y]-- == need[y]) miss++;
            }
            ans += left;
        }
        return ans;
    }
};

